Given three sorted arrays in non-decreasing order, find all common elements in non-decreasing order across these arrays. If there are no such elements return an empty array.Note: In case of duplicate common elements, include each element only once in the result.Examples: Input: a[] = [1, 5, 10, 20, 30], b[] = [5, 13, 15, 20], c[] = [5, 20] Output: 5 20Explanation: 5 and 20 are common in all the arrays.Input: a[] = [1, 2, 3, 4, 5], b[] = [6, 7], c[] = [8, 9, 10]Output: []Explanation: There are no common elements in a, b and c.Input: a[] = [2, 5, 10, 30], b[] = [5, 20, 34], c[] = [5, 13, 19]Output: 5Explanation: 5 is common in all the arrays.Try It YourselfTable of Content[Naive Approach] Using Hash Map or Dictionary[Expected Approach] Using three pointers - O(n1 + n2 + n3) Time and O(1) Space[Naive Approach] Using Hash Map or DictionaryThe idea is to use a Hash Map to track elements common across all three arrays while avoiding duplicates. Each element is marked step-by-step to identify those present in all arrays, and the final result is sorted to maintain non-decreasing order.Dry run for a[] = [1, 5, 10, 20, 30], b[] = [5, 13, 15, 20], c[] = [5, 20]:Process array a, store unique elements as key and value as 1, count = {1:1, 5:1, 10:1, 20:1, 30:1}Process array b, update only common elements 5 and 20 from 1 to 2, count = {1:1, 5:2, 10:1, 20:2, 30:1}Process array c, update only common elements 5 and 20 from 2 to 3, count = {1:1, 5:3, 10:1, 20:3, 30:1}Collect elements with value = 3, common = [5, 20]Sort the result, common = [5, 20]Final output, 5 20Important Points:We can also use a Self Balancing BST (like Tree Map) which maintains elements in sorted order automatically.However, in languages like Python and JavaScript, there is no built-in Self Balancing BST, so we use a Hash Map or Dictionary for processing and then sort the result at the end.
            C++

    #include <iostream>
#include <unordered_map>
#include <vector>
#include <algorithm>
using namespace std;

vector<int> commonElements(vector<int>& a, 
                vector<int>& b, vector<int>& c)
{
    unordered_map<int, int> count;

    // Process arr1 (store only unique elements)
    for (int i = 0; i < a.size(); i++) {
        if (i == 0 || a[i] != a[i - 1])
            count[a[i]] = 1;
    }

    // Process arr2
    for (int i = 0; i < b.size(); i++) {
        if (i == 0 || b[i] != b[i - 1]) {
            if (count[b[i]] == 1)
                count[b[i]] = 2;
        }
    }

    // Process arr3
    for (int i = 0; i < c.size(); i++) {
        if (i == 0 || c[i] != c[i - 1]) {
            if (count[c[i]] == 2)
                count[c[i]] = 3;
        }
    }

    // Collect common elements
    vector<int> common;
    for (auto &p : count) {
        if (p.second == 3)
            common.push_back(p.first);
    }

    // Sort result 
    sort(common.begin(), common.end());

    return common;
}

int main()
{
    vector<int> a = {1, 5, 10, 20, 30};
    vector<int> b = {5, 13, 15, 20};
    vector<int> c = {5, 20};

    vector<int> common = commonElements(a, b, c);

    if (common.empty())
        cout << "[]" << endl;
    else
        for (int ele : common)
            cout << ele << " ";

    return 0;
}


