        int[] a = {1, 5, 10, 20, 30};
        int[] b = {5, 13, 15, 20};
        int[] c = {5, 20};

        ArrayList<Integer> common = commonElements(a, b, c);

        if (common.isEmpty())
            System.out.println("[]");
        else
            for (int ele : common)
                System.out.print(ele + " ");
    }
}


